/**
 * Eliza API Client
 *
 * A TypeScript client for the Eliza API (Yandex's internal Anthropic proxy).
 * Provides quota management and token selection based on remaining balance.
 *
 * @example
 * ```typescript
 * import { ElizaClient } from './eliza';
 *
 * const client = new ElizaClient();
 *
 * // Get balance for a single token
 * const balance = await client.getBalance(token, 'my-token-key');
 * console.log(`Daily remaining: ${balance.dailyRemaining}`);
 * console.log(`Monthly remaining: ${balance.monthlyRemaining}`);
 *
 * // Select best token from multiple
 * const tokens = [
 *   { token: 'token1', tokenKey: 'key1' },
 *   { token: 'token2', tokenKey: 'key2' },
 * ];
 * const { token, balance } = await client.selectBestToken(tokens);
 * console.log(`Selected token: ${balance.tokenKey}`);
 * ```
 */
export { ElizaClient } from "./client.js";
export type { ElizaClientConfig } from "./client.js";
export { ElizaApiError, ElizaNetworkError, ElizaTimeoutError, NoAvailableTokensError, } from "./client.js";
export type { ElizaError, ElizaLimits, ElizaPeriodQuota, ElizaPeriodUsage, ElizaPoolInfoResponse, ElizaPoolPayload, ElizaPoolUpdateResponse, ElizaQuotaData, ElizaQuotaResponse, ElizaUsageData, ElizaUsageResponse, ElizaUsageValues, TokenBalance, TokenSelectionResult, TokenWithPool, } from "./types.js";
export { ModelResolver, ModelNotFoundError, UnsupportedVendorError, } from "./model-resolver.js";
export type { ElizaModel, ElizaModelsResponse, ModelArchitecture, ModelPrices, ModelResolverConfig, ResolvedModel, SupportedVendor, } from "./model-resolver.js";
